  q2: ['Quiz 2', ['minreq', 'oobe', 'easybcd', 'dualboot', 'wu', 'oem', 'accttypes', 'tmpfold', 'rufus', 'surfaceuefi', 'upg3', 'licswap', 'postinstall', 'lic6']],
  q3: ['Quiz 3', ['chkdskf', 'shortcuts', 'snap', 'start8', 'appgroups', 'jumplist', 'taskview', 'peek', 'startfolders', 'taskbarset', 'notifset', 'startsearch']],
